针对如tab栏快速切换加载数据时，由于ajax是异步的，有时不能做加载动画防止快速点击，此时快速切换时，如A、B两栏快速切换，A栏切换请求接口；B栏切换请求接口；此时AB快速切换，接口跟不上，容易造成数据错乱，为了解决这种情况，就需要用到请求取消
需要注意的是axios提供的cancelToken仅仅只是对相同的同一个接口有效，可以取消。如果遇见多个接口需要防止这种取消之前的接口时，需要重新使用axios.CancelToken创建一个实例
效果如图

封装一个简易的axios/* * @Author: your name * @Date: 2021-12-16 13:59:33 * @LastEditTime: 2021-12-17 08:53:19 * @LastEditors: Please set LastEditors * @Description: 打开koroFileHeader查看配置 进行设置: https://github.com/OBKoro1/koro1FileHeader/wiki/%E9%85%8D%E7%BD%AE * @FilePath: \vue1\axios.js */import axios from &#x27;axios&#x27;;const getFn =  (url, data, that,CancelToken) =&gt; &#123;    const result = axios.get(url, &#123;        params: data,        cancelToken: new CancelToken(function executor(c) &#123;            // executor 函数接收一个 cancel 函数作为参数                if(that)&#123;                that.cancel = c;                           &#125;                      &#125;)    &#125;);    return result;&#125;export default getFn;



调用&lt;!-- * @Author: your name * @Date: 2021-12-16 13:41:59 * @LastEditTime: 2021-12-17 15:08:00 * @LastEditors: Please set LastEditors * @Description: 打开koroFileHeader查看配置 进行设置: https://github.com/OBKoro1/koro1FileHeader/wiki/%E9%85%8D%E7%BD%AE   * @FilePath: \vue1\src\App.vue--&gt;&lt;template&gt;  &lt;div id=&quot;app&quot;&gt;    &lt;h1&gt;app.vue&lt;/h1&gt;    &lt;hr /&gt;    &lt;div&gt;      &lt;button        @click=&quot;getData1(11)&quot;        :class=&quot;btnName === &#x27;个人笔记&#x27; ? &#x27;active&#x27; : &#x27;&#x27;&quot;      &gt;        请求个人笔记      &lt;/button&gt;      &lt;button        @click=&quot;getData1(12)&quot;        :class=&quot;btnName === &#x27;面试题&#x27; ? &#x27;active&#x27; : &#x27;&#x27;&quot;      &gt;        请求面试题      &lt;/button&gt;      &lt;button @click=&quot;cancelFn&quot;&gt;取消&lt;/button&gt;    &lt;/div&gt;    &lt;ul v-if=&quot;list.length &gt; 0&quot;&gt;      &lt;li v-for=&quot;(item, index) in list&quot; :key=&quot;index&quot;&gt;        【&#123;&#123; btnName &#125;&#125;】--- &#123;&#123; item.title &#125;&#125;      &lt;/li&gt;    &lt;/ul&gt;    &lt;div v-else&gt;没有相关数据&lt;/div&gt;  &lt;/div&gt;&lt;/template&gt;&lt;script&gt;import getFn from &quot;../axios&quot;;import axios from &quot;axios&quot;;export default &#123;  name: &quot;App&quot;,  data() &#123;    return &#123;      list: [],      btnName: &quot;个人笔记&quot;,      cancel: &quot;&quot;,      CancelToken: &quot;&quot;,    &#125;;  &#125;,  created() &#123;    this.CancelToken = axios.CancelToken;    this.source = this.CancelToken.source();    this.getData1();  &#125;,  methods: &#123;    cancelFn() &#123;      const that = this;      if (that.source) &#123;        that.source.cancel();        this.source = this.CancelToken.source();      &#125;    &#125;,    async getData1(typeId = 11) &#123;      if (typeId === 11) &#123;        this.btnName = &quot;个人笔记&quot;;      &#125; else &#123;        this.btnName = &quot;面试题&quot;;      &#125;      const that = this;      if (this.cancel) &#123;        this.cancel();      &#125;      getFn(        &quot;https://www.shaoyuhong.cn/grzx/findNoteList.php&quot;,        &#123; page: 1, type_id: typeId &#125;,        that,        that.CancelToken      ).then((res) =&gt; &#123;        const &#123; code, list &#125; = res.data;        if (code === 200) &#123;          this.list = list;        &#125;      &#125;);    &#125;,  &#125;,&#125;;&lt;/script&gt;&lt;style&gt;#app &#123;  font-family: &quot;Avenir&quot;, Helvetica, Arial, sans-serif;  -webkit-font-smoothing: antialiased;  -moz-osx-font-smoothing: grayscale;  text-align: center;  color: #2c3e50;  margin-top: 60px;&#125;button.active &#123;  background-color: red;  color: #fff;&#125;&lt;/style&gt;

generator开始&lt;script&gt;    function *g()&#123;        console.log(&#x27;g fn is start&#x27;);        yield;        console.log(&#x27;console.log b is start&#x27;);        yield;        console.log(&#x27;end&#x27;)    &#125;    var generator = g();    generator.next(); //g fn is start     [yield会像return一样返回值，&#123;value: undefined, done: false&#125;]	generator.next(); // console.log b is start     [yield会像return一样返回值，&#123;value: undefined, done: false&#125;]    generator.next(); //end                  [yield会像return一样返回值，&#123;value: undefined, done: true&#125;]&lt;/script&gt;

generator生成器是用法和普通函数相同，遇到yield暂停，使用next将执行一下yeild
done为true时，当前generator生成器执行完成 
generator next传参与执行顺序&lt;script&gt;    function *g(defaultValue)&#123;        console.log(defaultValue);        console.log(&#x27;g fn is start&#x27;);        const nextValue1 = yield &#x27;yield1 result&#x27;;        console.log(&#x27;nextValue1=&#x27;,nextValue1)        console.log(&#x27;console.log b is start&#x27;);        const nextValue2 = yield &#x27;yield2 result&#x27;;        console.log(&#x27;nextValue2=&#x27;,nextValue2);        console.log(defaultValue);        console.log(&#x27;end&#x27;);        return &#x27;function end&#x27;;  //如果有return  res3.value就有值，没有return  res3.value的值是空的undefind    &#125;    var generator = g(&#x27;default&#x27;);   const res1 =  generator.next();   console.log(&#x27;res1:&#x27;,res1);   const res2 = generator.next(&#x27;100&#x27;);   console.log(&#x27;res2:&#x27;,res2);   const res3 = generator.next(200);   console.log(&#x27;res3:&#x27;,res3);&lt;/script&gt;

defaultg fn is startres1: {value: ‘yield1 result’, done: false}nextValue1= 100console.log b is startres2: {value: ‘yield2 result’, done: false}nextValue2= 200defaultendres3: {value: ‘function end’, done: true}
如何更好理解上面的执行打印结果先简化一下
function *g(defaultValue)&#123;   /*  const nextValue1 = yield &#x27;yield1 result&#x27;;     console.log(&#x27;nextValue1=&#x27;,nextValue1)     console.log(&#x27;console.log b is start&#x27;);    */        /*  =======以上代码等同于===========*/    1. 返回 &#x27;yield1 result&#x27;    2. yield   并执行到当前这里    3. const nextValue1 = next传递的参数    所以nextValue1的值其实是在下一个next中执行的 &#125; var generator = g(&#x27;default&#x27;);const res1 =  generator.next();console.log(&#x27;res1:&#x27;,res1);const res2 = generator.next(&#x27;100&#x27;);console.log(&#x27;res2:&#x27;,res2);



解决回调地狱问题function request(count)&#123;     return new Promise((resolve,reject)=&gt;&#123;          setTimeout(()=&gt;&#123;              const result = count+1;              resolve(result);          &#125;,1000)      &#125;);   &#125;   function *g(defaultCount)&#123;       const count1 = yield request(defaultCount);       console.log(&#x27;count1:&#x27;,count1)       const count2 = yield request(count1);       console.log(&#x27;count2:&#x27;,count2)       const count3 = yield request(count2);       console.log(&#x27;count3:&#x27;,count3)       const count4 = yield request(count3);       console.log(&#x27;count4:&#x27;,count4)       return count4;   &#125;  var g1 = g(1); function run(count= null)&#123;     const promiseFn = g1.next(count);     if(!promiseFn.done)&#123;       promiseFn.value.then(res=&gt;&#123;          run(res);       &#125;)     &#125;  &#125;  run();

输出结果为每等待1S输出一个结果 :
count1: 2count2: 3count3: 4count4: 5

网络布局
display:grid/grid-inline  grid块级元素，inline-grid 行内元素。使用网络布局会将行内元素都统一转成块级/行内
grid-template-rows: repeat(3,1fr);grid-template-columns: repeat(3,1fr);/** 1 1 1 2  **/grid-template-rows: repeat(3,1fr) 2fr;grid-template-columns: repeat(3,1fr) 2fr/** 百分数 **/grid-template-columns: repeat(3,33.333%);grid-template-rows: repeat(3,33.333%); /** 两边固定，中间自适应  **/grid-template-rows: 100px 1fr 100px;grid-template-columns: repeat(3,33.33%);/** auto-fill **/grid-template-columns: repeat(auto-fill,25%); /* 1/0.25 = 4,自动计算 */grid-template-rows: repeat(auto-fill,25%);  /** 还可以是具体px,如100px时，会根据父级，自动计算出数量   **/

minmax(100px,200px)  根据情况选择最小值，或者最大值
grid-template-columns: 200px 300px minmax(100px,200px);



row-gap: 20px;   column-gap: 20px;  行、列间隔，添加连线时可以不用box-sizing

网络合并
合并时，与dom顺序无关，主要和命名位置有关
    &lt;style&gt;        *&#123;            margin:0;            padding: 0;        &#125;        section&#123;            display: grid;            border: 2px solid #ddd;            width: 600px;            height: 600px;            grid-template-columns: repeat(3,1fr);            grid-template-rows: repeat(3,1fr);            row-gap: 20px;            column-gap: 20px;            grid-template-areas: &#x27;a a c&#x27;                                 &#x27;a a f&#x27;                                 &#x27;j h f&#x27;;        &#125;        section&gt;div&#123;            border:1px solid red;        &#125;        section&gt;div:nth-of-type(1)&#123;             grid-area: a;        &#125;        section&gt;div:nth-of-type(3)&#123;             grid-area: f;        &#125;    &lt;/style&gt;&lt;/head&gt;&lt;body&gt;    &lt;section id=&quot;grid&quot;&gt;        &lt;div&gt;1&lt;/div&gt;        &lt;div&gt;2&lt;/div&gt;        &lt;div&gt;3&lt;/div&gt;        &lt;div&gt;4&lt;/div&gt;        &lt;div&gt;5&lt;/div&gt;    &lt;/section&gt;   &lt;/body&gt;





