xhr.upload.onprogress = function(ev)&#123;    console.log(&#x27;进度：&#x27;+(100*ev.loaded/ev.total).toFixed(2)+&#x27;%&#x27;);&#125;



contenteditable=&quot;true&quot;属性让div+css可以相当于Input     //&lt;div&gt;....标签均可修改内容 不限标签输入框 &lt;input type=&quot;text&quot; x-webkit-speech /&gt;  //语音输入



//桌面提醒function showNotification() &#123;               // window.Notification.permission = &quot;granted&quot;;                               if(window.Notification) &#123;                    if(window.Notification.permission == &quot;granted&quot;) &#123;                        var notification = new Notification(&#x27;你有一条新信息&#x27;, &#123;                            body: &quot;你好我是王小婷&quot;,                            icon: &quot;https://ss2.bdstatic.com/70cFvnSh_Q1YnxGkpoWK1HF6hhy/it/u=1422784010,1847471088&amp;fm=27&amp;gp=0.jpg&quot;                        &#125;);                        setTimeout(function() &#123; notification.close(); &#125;, 50000);                    &#125; else &#123;                        window.Notification.requestPermission();                    &#125;                &#125; else alert(&#x27;你的浏览器不支持此消息提示功能，请使用chrome内核的浏览器！&#x27;);            &#125;;

&lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt;&lt;head&gt;    &lt;meta charset=&quot;UTF-8&quot;&gt;    &lt;meta http-equiv=&quot;X-UA-Compatible&quot; content=&quot;IE=edge&quot;&gt;    &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt;    &lt;title&gt;Document&lt;/title&gt;&lt;/head&gt;&lt;body&gt;    &lt;input type=&quot;text&quot; id=&quot;text&quot;&gt;    &lt;button id=&quot;btn&quot;&gt;发送&lt;/button&gt;    &lt;ul id=&quot;ul&quot;&gt;&lt;/ul&gt;    &lt;hr/&gt;    &lt;iframe src=&quot;./2.html&quot; width=&quot;1000&quot; height=&quot;400&quot;&gt;&lt;/iframe&gt;&lt;/body&gt;&lt;/html&gt;&lt;script&gt;       var oText = document.querySelector(&quot;#text&quot;);       var oBtn = document.querySelector(&quot;#btn&quot;);       oBtn.onclick=function()&#123;            if(oText.value)&#123;                  var oIframe = document.querySelector(&quot;iframe&quot;);                  oIframe.contentWindow.postMessage(oText.value);            &#125;       &#125;       window.addEventListener(&quot;message&quot;,(&#123;data&#125;)=&gt;&#123;              var oLi = document.createElement(&quot;li&quot;);              var oText = document.createTextNode(data);              oLi.appendChild(oText);              document.querySelector(&quot;#ul&quot;).appendChild(oLi);         &#125;)&lt;/script&gt;

&lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt;&lt;head&gt;    &lt;meta charset=&quot;UTF-8&quot;&gt;    &lt;meta http-equiv=&quot;X-UA-Compatible&quot; content=&quot;IE=edge&quot;&gt;    &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt;    &lt;title&gt;Document&lt;/title&gt;&lt;/head&gt;&lt;body&gt;    &lt;h4&gt;收到的消息是&lt;/h4&gt;    &lt;ul id=&quot;ul&quot;&gt;          &lt;/ul&gt;    &lt;input type=&quot;text&quot; id=&quot;text&quot;&gt;    &lt;button id=&quot;btn&quot;&gt;给父级发送消息&lt;/button&gt;&lt;/body&gt;&lt;/html&gt;&lt;script&gt;    window.addEventListener(&quot;message&quot;,function(&#123;data&#125;)&#123;        var oUl = document.querySelector(&quot;#ul&quot;);        var oLi = document.createElement(&quot;li&quot;);        var oText = document.createTextNode(data);        oLi.appendChild(oText);        oUl.appendChild(oLi);    &#125;)   var oBtn = document.querySelector(&quot;#btn&quot;);   var oText = document.querySelector(&quot;#text&quot;);   oBtn.onclick=function()&#123;         var value = oText.value;         if(value)&#123;             parent.postMessage(value);         &#125;        &#125;&lt;/script&gt;



iframe多层嵌套window.frames[0].frame[0].frame[0].postMessage(‘值’); //window指向当前层，该代码可以由A层直接到D层
相同,parent.postMessage();可以由子向父传值 
parent.parent.parent.postMesage(); 可以向父级之上的父级传值 
top.postMessage()可以向顶层传值

js原生实现div交换顺序动画参考代码&lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt;&lt;head&gt;    &lt;meta charset=&quot;UTF-8&quot;&gt;    &lt;meta http-equiv=&quot;X-UA-Compatible&quot; content=&quot;IE=edge&quot;&gt;    &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt;    &lt;title&gt;Document&lt;/title&gt;    &lt;style&gt;        *&#123;            margin:0;            padding:0;        &#125;      #ul&#123;          width:1000px;          border:1px solid red;          margin:0 auto;          position: relative;      &#125;      ul,li&#123;          list-style-type: none;      &#125;       #ul&gt;li&#123;           width:200px;           height:200px;           position: absolute;           font-size:60px;           text-align: center;           line-height: 200px;           color:#fff;           cursor: pointer;           user-select: none;           transition: all .5s cubic-bezier(0.395, 1.650, 0.525, 0.745);       &#125;    &lt;/style&gt;&lt;/head&gt;&lt;body&gt;    &lt;ul id=&quot;ul&quot;&gt;         &lt;/ul&gt;&lt;/body&gt;&lt;/html&gt;&lt;script&gt;     function createLi()&#123;        var oUl = document.querySelector(&quot;#ul&quot;);        for(let i = 1;i&lt;21;i++)&#123;            let tag = document.createElement(&quot;li&quot;);            let text = document.createTextNode(i);            tag.draggable=true;            tag.appendChild(text);            oUl.appendChild(tag);        &#125;     &#125;     function computedLiPostion()&#123;        var oUl = document.querySelector(&quot;#ul&quot;);        var oLi = oUl.getElementsByTagName(&quot;li&quot;);        oUl.style.height = Math.ceil(oLi.length / 5) * oLi[0].offsetHeight+1 + &#x27;px&#x27;;        var left =0,top=0;        for(var i=0,length = oLi.length;i&lt;length;i++)&#123;            const bg = `rgb($&#123;parseInt(Math.random() * 256)&#125;,$&#123;parseInt(Math.random() * 256)&#125;,$&#123;parseInt(Math.random() * 256)&#125;)`;            oLi[i].style.cssText= `;left:$&#123;left&#125;px;top:$&#123;top&#125;px;background-color:$&#123;bg&#125;`;              left=left+oLi[0].offsetWidth;              if(left &gt;=1000)&#123;                  left=0;                  top+=oLi[0].offsetHeight;              &#125;                      &#125;     &#125;    function getStyle(element,attr)&#123;          if(element.currentStyle)&#123;              return element.currentStyle[attr]          &#125;else&#123;              console.log(window.getComputedStyle(element));              return window.getComputedStyle(element)[attr]          &#125;    &#125;     function changePosition()&#123;        var oUl = document.querySelector(&quot;#ul&quot;);        var oLi = oUl.getElementsByTagName(&quot;li&quot;);        for(var i=0,length=oLi.length;i&lt;length;i++)&#123;            oLi[i].index= i;            var startIndex=0,endIndex=0;            oLi[i].ondragstart=function(e)&#123;                 startIndex = this.index;            &#125;            oLi[i].ondragend=function(e)&#123;                 e.preventDefault();            &#125;            oLi[i].ondragover=function(e)&#123;                e.preventDefault();            &#125;            oLi[i].ondrop=function(e)&#123;                 e.preventDefault();                 endIndex = this.index;                 for(let j=0,length=oLi.length;j&lt;length;j++)&#123;                     oLi[j].style.zIndex = 1;                 &#125;                 let fromX = getStyle(oLi[startIndex],&#x27;left&#x27;);                 let fromY  = getStyle(oLi[startIndex],&#x27;top&#x27;);                 let toX = getStyle(oLi[endIndex],&#x27;left&#x27;);                 let toY = getStyle(oLi[endIndex],&#x27;top&#x27;);                 oLi[startIndex].style.cssText+=`;z-index:100;left:$&#123;toX&#125;;top:$&#123;toY&#125;`;                 oLi[endIndex].style.cssText+=`;z-index:100;left:$&#123;fromX&#125;;top:$&#123;fromY&#125;`;            &#125;        &#125;     &#125;     createLi();     computedLiPostion();     changePosition();&lt;/script&gt;




上面代码有一个隐藏的问题，当快速拖动时，会出现块与块交换时出现错位的的情况，考虑是使用transition过渡的时候不能取到最终值，经过尝试，放弃直接获取style的方法来交换位置，改用在元素实例上添加自定义属性

参考代码如下，解决快速拖动时的错位问题&lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt;&lt;head&gt;    &lt;meta charset=&quot;UTF-8&quot;&gt;    &lt;meta http-equiv=&quot;X-UA-Compatible&quot; content=&quot;IE=edge&quot;&gt;    &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt;    &lt;title&gt;Document&lt;/title&gt;    &lt;style&gt;        *&#123;            margin:0;            padding:0;        &#125;      #ul&#123;          width:1000px;          border:1px solid red;          margin:0 auto;          position: relative;      &#125;      ul,li&#123;          list-style-type: none;      &#125;       #ul&gt;li&#123;           width:200px;           height:200px;           position: absolute;           font-size:60px;           text-align: center;           line-height: 200px;           color:#fff;           cursor: pointer;           user-select: none;           transition: all .5s cubic-bezier(0.395, 1.650, 0.525, 0.745);       &#125;    &lt;/style&gt;&lt;/head&gt;&lt;body&gt;    &lt;ul id=&quot;ul&quot;&gt;         &lt;/ul&gt;&lt;/body&gt;&lt;/html&gt;&lt;script&gt;     function createLi()&#123;        var oUl = document.querySelector(&quot;#ul&quot;);        for(let i = 1;i&lt;21;i++)&#123;            let tag = document.createElement(&quot;li&quot;);            let text = document.createTextNode(i);            tag.draggable=true;            tag.appendChild(text);            oUl.appendChild(tag);        &#125;     &#125;     function computedLiPostion()&#123;        var oUl = document.querySelector(&quot;#ul&quot;);        var oLi = oUl.getElementsByTagName(&quot;li&quot;);        oUl.style.height = Math.ceil(oLi.length / 5) * oLi[0].offsetHeight+1 + &#x27;px&#x27;;        var left =0,top=0;        for(var i=0,length = oLi.length;i&lt;length;i++)&#123;            const bg = `rgb($&#123;parseInt(Math.random() * 256)&#125;,$&#123;parseInt(Math.random() * 256)&#125;,$&#123;parseInt(Math.random() * 256)&#125;)`;            oLi[i].style.cssText= `;left:$&#123;left&#125;px;top:$&#123;top&#125;px;background-color:$&#123;bg&#125;`;              left=left+oLi[0].offsetWidth;              if(left &gt;=1000)&#123;                  left=0;                  top+=oLi[0].offsetHeight;              &#125;                      &#125;     &#125;    function getStyle(element,attr)&#123;          if(element.currentStyle)&#123;              return element.currentStyle[attr]          &#125;else&#123;               return window.getComputedStyle(element)[attr]          &#125;    &#125;     function changePosition()&#123;        var oUl = document.querySelector(&quot;#ul&quot;);        var oLi = oUl.getElementsByTagName(&quot;li&quot;);        for(var i=0,length=oLi.length;i&lt;length;i++)&#123;            oLi[i].index= i;            oLi[i].x = getStyle(oLi[i],&#x27;left&#x27;);            oLi[i].y = getStyle(oLi[i],&#x27;top&#x27;);            var startIndex=0,endIndex=0;            oLi[i].ondragstart=function(e)&#123;                 startIndex = this.index;            &#125;            oLi[i].ondragend=function(e)&#123;                 e.preventDefault();            &#125;            oLi[i].ondragover=function(e)&#123;                e.preventDefault();            &#125;            oLi[i].ondrop=function(e)&#123;                 e.preventDefault();                 endIndex = this.index;                 for(let j=0,length=oLi.length;j&lt;length;j++)&#123;                     oLi[j].style.zIndex = 1;                 &#125;                 let fromX =oLi[startIndex].x;                 let fromY  = oLi[startIndex].y                 let toX =oLi[endIndex].x;                 let toY = oLi[endIndex].y;                 oLi[startIndex].x = toX;                 oLi[startIndex].y = toY;                 oLi[endIndex].x = fromX;                 oLi[endIndex].y = fromY;                 oLi[startIndex].style.cssText+=`;z-index:100;left:$&#123;toX&#125;;top:$&#123;toY&#125;`;                 oLi[endIndex].style.cssText+=`;z-index: