1.动态路由app.routing.module.js   &#123;path:&#x27;details/:id&#x27;,component:DetailsComponent&#125;,&lt;a [routerLink]=&quot;[&#x27;/home/details&#x27;,item.id]&quot; routerLinkActive=&quot;router-link-active&quot; &gt; 接收import &#123; Component, OnInit &#125; from &#x27;@angular/core&#x27;;import &#123; ActivatedRoute &#125; from &#x27;@angular/router&#x27;;@Component(&#123;  selector: &#x27;app-details&#x27;,  templateUrl: &#x27;./details.component.html&#x27;,  styleUrls: [&#x27;./details.component.less&#x27;]&#125;)export class DetailsComponent implements OnInit &#123;  routerInfo:any = null;  constructor(public info:ActivatedRoute) &#123;     &#125;  ngOnInit(): void &#123;    this.info.params.subscribe(data=&gt;&#123;      this.routerInfo = data;    &#125;)  &#125;&#125;[相关链接参考]: https://www.angular.cn/guide/router#accessing-query-parameters-and-fragments2.Get方式传参 &lt;a [routerLink]=&quot;[&#x27;/home/details&#x27;]&quot; [queryParams] = &quot;&#123;id:item.id,age:22,school:&#x27;重庆大学&#x27;&#125;&quot; routerLinkActive=&quot;router-link-active&quot; &gt; 接收import &#123; Component, OnInit &#125; from &#x27;@angular/core&#x27;;import &#123; ActivatedRoute &#125; from &#x27;@angular/router&#x27;;@Component(&#123;  selector: &#x27;app-details&#x27;,  templateUrl: &#x27;./details.component.html&#x27;,  styleUrls: [&#x27;./details.component.less&#x27;]&#125;)export class DetailsComponent implements OnInit &#123;  routerInfo:any = null;  constructor(public info:ActivatedRoute) &#123;     &#125;  ngOnInit(): void &#123;    this.info.queryParams.subscribe(data=&gt;&#123;      this.routerInfo = data;    &#125;)  &#125;&#125;//总结：动态路由使用this.router.params.subscribe监听。普通路由get传参使用this.router.queryParams.subscribe(data=&gt;&#123;&#125;)监听




